import java.math.BigInteger;
import java.util.*;

public class Main {
    static final BigInteger MOD_BI = BigInteger.valueOf(998244353L);
    static final long MOD = 998244353L;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();

        int max = n + m;
        long[] fact = new long[max + 1];
        long[] invFact = new long[max + 1];
        fact[0] = 1;
        for (int i = 1; i <= max; ++i) fact[i] = fact[i - 1] * i % MOD;
        invFact[max] = BigInteger.valueOf(fact[max]).modInverse(MOD_BI).longValue();
        for (int i = max; i >= 1; --i) invFact[i - 1] = invFact[i] * i % MOD;

        long phaseSize = 1;
        long p = 1;
        for (int i = 0; p != 0; ++i) {
            p = multiply(p, n - i, smallInv(n + m - i, fact, invFact));
            phaseSize += p;
            if (phaseSize >= MOD) phaseSize -= MOD;
        }

        long ans = 0;
        for (int k = 1; k <= n; ++k) {
            long sign = ((k + 1) & 1) == 0 ? 1 : MOD - 1;
            long numPhases = multiply(m + k, smallInv(k, fact, invFact));
            long ncr = multiply(fact[n], invFact[k], invFact[n - k]);
            long term = multiply(sign, ncr, numPhases, phaseSize);
            ans += term;
            if (ans >= MOD) ans -= MOD;
        }
        System.out.println(ans);
    }

    static long multiply(long... xs) {
        long r = 1;
        for (long x : xs) r = r * x % MOD;
        return r;
    }

    static long smallInv(int x, long[] fact, long[] invFact) {
        return invFact[x] * fact[x - 1] % MOD;
    }
}
